import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function StudentDashboard({ userName, userUsername, grade, phone, address, handleLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [materials, setMaterials] = useState([]);
  const [timetable, setTimetable] = useState([]);
  const [quizzes, setQuizzes] = useState([]);

  // Database එකෙන් දත්ත ලබාගැනීම
  const fetchStudentData = () => {
    // 1. පාඩම් ද්‍රව්‍ය ලබාගැනීම
    axios.get('http://localhost:8081/api/learning-materials')
      .then(res => {
        // සිසුවාගේ පන්තියට (Grade) ගැලපෙන පාඩම් විතරක් ෆිල්ටර් කරගන්නවා
        const filtered = res.data.filter(m => m.grade === grade);
        setMaterials(filtered);
      }).catch(err => console.log(err));

    // 2. කාලසටහන ලබාගැනීම
    axios.get('http://localhost:8081/api/timetable')
      .then(res => {
        // සිසුවාගේ පන්තියට අදාළ පන්ති විතරක් ෆිල්ටර් කරගන්නවා
        const filtered = res.data.filter(c => c.grade === grade);
        setTimetable(filtered);
      }).catch(err => console.log(err));

    // 3. ක්විස් (Quizzes) ලබාගැනීම
    axios.get('http://localhost:8081/api/quizzes')
      .then(res => {
        // සිසුවාගේ පන්තියට අදාළ ක්විස් විතරක් ෆිල්ටර් කරගන්නවා
        const filtered = res.data.filter(q => q.grade === grade);
        setQuizzes(filtered);
      }).catch(err => console.log(err));
  };

  useEffect(() => {
    fetchStudentData();
  }, [grade]);

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            {/* Welcome Banner */}
            <div style={{ backgroundColor: '#15803d', padding: '30px', borderRadius: '15px', color: 'white', marginBottom: '30px', boxShadow: '0 4px 15px rgba(21,128,61,0.2)', position: 'relative', overflow: 'hidden' }}>
              <div style={{ position: 'relative', zIndex: 2 }}>
                <h1 style={{ margin: '0 0 10px 0', fontSize: '28px' }}>Welcome back, {userName || 'Student'}! 🧑‍🎓</h1>
                <p style={{ margin: 0, opacity: 0.9, fontSize: '15px' }}>Access your online classrooms, download handouts, and join live quizzes instantly.</p>
              </div>
              <div style={{ position: 'absolute', right: '-10px', top: '-40px', fontSize: '150px', opacity: 0.1, zIndex: 1 }}>🎓</div>
            </div>
            
            {/* Stats Cards */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px', marginBottom: '30px' }}>
              <DashboardCard title="My Registered Grade" count={grade || 'Grade 10'} icon="🏫" color="#f5f3ff" textColor="#7c3aed" />
              <DashboardCard title="Available Handouts" count={`${materials.length} Materials`} icon="📂" color="#eff6ff" textColor="#3b82f6" />
              <DashboardCard title="Pending Quizzes" count={`${quizzes.length} Papers`} icon="📝" color="#fefce8" textColor="#eab308" />
            </div>

            {/* Timetable Section */}
            <h2 style={{ color: '#1e293b', margin: '0 0 15px 0', fontSize: '20px' }}>📅 My Class Timetable</h2>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '20px', marginBottom: '30px' }}>
                {timetable.length > 0 ? timetable.map(c => (
                  <div key={c.id} style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', borderTop: `5px solid #3b82f6` }}>
                    <div style={{ color: '#64748b', fontSize: '12px', fontWeight: 'bold', marginBottom: '5px' }}>{c.grade}</div>
                    <h3 style={{ margin: '0 0 10px 0', color: '#1e293b', fontSize: '18px' }}>{c.subject}</h3>
                    <p style={{ color: '#64748b', fontSize: '13px', margin: '0 0 15px 0' }}>🧑‍🏫 Teacher: {c.teacher}</p>
                    <div style={{ backgroundColor: '#f8fafc', padding: '10px', borderRadius: '8px', fontSize: '13px', color: '#334155', fontWeight: 'bold' }}>
                        🕒 {c.day} | {c.time_slot}
                    </div>
                  </div>
                )) : (
                  <p style={{ color: '#64748b', fontSize: '14px' }}>No live classes scheduled for your grade yet.</p>
                )}
            </div>
          </div>
        );

      case 'materials':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>📚 My Learning Materials ({grade})</h2>
            <div style={{ backgroundColor: 'white', padding: '20px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                <thead>
                  <tr style={{ borderBottom: '2px solid #e2e8f0', color: '#64748b', fontSize: '13px' }}>
                    <th style={{ padding: '12px 10px' }}>Material Title</th>
                    <th style={{ padding: '12px 10px' }}>Type</th>
                    <th style={{ padding: '12px 10px' }}>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {materials.map(m => (
                    <tr key={m.id} style={{ borderBottom: '1px solid #f1f5f9', fontSize: '14px' }}>
                      <td style={{ padding: '15px 10px', fontWeight: 'bold', color: '#334155' }}>{m.title}</td>
                      <td style={{ padding: '15px 10px' }}>
                        <span style={{ padding: '4px 10px', borderRadius: '4px', fontSize: '11px', fontWeight: 'bold', backgroundColor: m.material_type === 'PDF' ? '#fee2e2' : '#e0f2fe', color: m.material_type === 'PDF' ? '#ef4444' : '#0ea5e9' }}>
                          {m.material_type}
                        </span>
                      </td>
                      <td style={{ padding: '15px 10px' }}>
                        {m.material_type === 'PDF' ? (
                          <a href={`http://localhost:8081/${m.file_path}`} target="_blank" rel="noopener noreferrer" style={downloadBtnStyle}>
                            📥 Download PDF Handout
                          </a>
                        ) : (
                          <a href={m.file_path} target="_blank" rel="noopener noreferrer" style={videoBtnStyle}>
                            ▶️ Watch Video Lesson
                          </a>
                        )}
                      </td>
                    </tr>
                  ))}
                  {materials.length === 0 && (
                    <tr>
                      <td colSpan="3" style={{ padding: '30px', textAlign: 'center', color: '#94a3b8' }}>No learning materials found for your grade.</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        );

      case 'quiz':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>📝 Online Quizzes & Mock Exams</h2>
            <div style={{ backgroundColor: 'white', padding: '20px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                <thead>
                  <tr style={{ borderBottom: '2px solid #e2e8f0', color: '#64748b', fontSize: '13px' }}>
                    <th style={{ padding: '12px 10px' }}>Exam/Quiz Paper Title</th>
                    <th style={{ padding: '12px 10px' }}>Subject</th>
                    <th style={{ padding: '12px 10px', textAlign: 'center' }}>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {quizzes.map(q => (
                    <tr key={q.id} style={{ borderBottom: '1px solid #f1f5f9', fontSize: '14px' }}>
                      <td style={{ padding: '15px 10px', fontWeight: 'bold', color: '#1e293b' }}>{q.title}</td>
                      <td style={{ padding: '15px 10px', color: '#475569' }}>{q.subject_name}</td>
                      <td style={{ padding: '15px 10px', textAlign: 'center' }}>
                        <button onClick={() => alert("✏️ Opening MCQ Exam Window...")} style={startQuizBtn}>
                          Start Attempt 🚀
                        </button>
                      </td>
                    </tr>
                  ))}
                  {quizzes.length === 0 && (
                    <tr>
                      <td colSpan="3" style={{ padding: '30px', textAlign: 'center', color: '#94a3b8' }}>No active quiz papers found for your grade.</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        );

      case 'forum':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ margin: '0 0 20px 0', color: '#1e293b' }}>💬 Student Discussion Forum</h2>
            <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
                <div style={{ padding: '20px', border: '1px solid #e2e8f0', borderRadius: '12px', backgroundColor: '#f8fafc', marginBottom: '20px' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                        <span style={{ fontWeight: 'bold', color: '#b45309', fontSize: '14px' }}>📢 Teacher Announcement</span>
                        <span style={{ fontSize: '12px', color: '#64748b' }}>Yesterday</span>
                    </div>
                    <p style={{ margin: 0, color: '#1e293b', fontSize: '14px', fontWeight: 'bold' }}>Dear Students, please make sure to download the Term Test Revision PDF and complete it before Saturday's live class!</p>
                </div>
                
                <h3 style={{ margin: '20px 0 15px 0', color: '#1e293b', fontSize: '16px' }}>Ask a Question from Teacher</h3>
                <div style={{ display: 'flex', gap: '15px' }}>
                    <input type="text" placeholder="Type your question here..." style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #cbd5e1' }} />
                    <button onClick={() => alert("✅ Question sent to the teacher successfully!")} style={{ padding: '12px 30px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' }}>Ask</button>
                </div>
            </div>
          </div>
        );

      case 'profile':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ margin: '0 0 20px 0', color: '#1e293b' }}>👤 Student My Profile Settings</h2>
            <div style={{ display: 'flex', gap: '20px', flexWrap: 'wrap' }}>
                <div style={{ flex: '1 1 400px', backgroundColor: 'white', padding: '35px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
                    <h3 style={{ color: '#15803d', margin: '0 0 20px 0', borderBottom: '2px solid #f1f5f9', paddingBottom: '10px' }}>My Academic Information</h3>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                        <div><label style={labelStyle}>Full Name</label><input type="text" value={userName} disabled style={disabledInput} /></div>
                        <div><label style={labelStyle}>Login Username</label><input type="text" value={userUsername} disabled style={disabledInput} /></div>
                        <div><label style={labelStyle}>Current Registered Grade</label><input type="text" value={grade || 'Grade 10'} disabled style={{...disabledInput, color: '#7c3aed', fontWeight: 'bold'}} /></div>
                        <div><label style={labelStyle}>Contact Mobile Number</label><input type="text" value={phone || 'Not Provided'} disabled style={disabledInput} /></div>
                        <div><label style={labelStyle}>Residential Address</label><input type="text" value={address || 'Not Provided'} disabled style={disabledInput} /></div>
                    </div>
                </div>
            </div>
          </div>
        );
      default: return null;
    }
  };

  return (
    <div style={{ display: 'flex', height: '100vh', overflow: 'hidden', backgroundColor: '#f8fafc', fontFamily: 'sans-serif', width: '100%' }}>
      
      {/* වම්පස සයිඩ්බාර් එක */}
      <div style={{ width: '260px', backgroundColor: '#145c2e', color: 'white', padding: '30px 0', display: 'flex', flexDirection: 'column', boxShadow: '4px 0 15px rgba(0,0,0,0.1)', flexShrink: 0 }}>
        <div style={{ padding: '0 25px', marginBottom: '40px', textAlign: 'center' }}>
            <h2 style={{ margin: 0, fontSize: '24px' }}>Aura Pen Saku</h2>
            <p style={{ color: '#86efac', margin: '5px 0 0 0', fontSize: '12px', fontWeight: 'bold' }}>STUDENT PORTAL</p>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px', padding: '0 15px', overflowY: 'auto' }}>
          <SidebarBtn active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon="🏠" text="Dashboard" />
          <SidebarBtn active={activeTab === 'materials'} onClick={() => setActiveTab('materials')} icon="📚" text="My Materials" />
          <SidebarBtn active={activeTab === 'quiz'} onClick={() => setActiveTab('quiz')} icon="📝" text="Online Exams" />
          <SidebarBtn active={activeTab === 'forum'} onClick={() => setActiveTab('forum')} icon="💬" text="Class Forum" />
          <SidebarBtn active={activeTab === 'profile'} onClick={() => setActiveTab('profile')} icon="👤" text="My Profile" />
        </div>
        <div style={{ marginTop: 'auto', padding: '20px 15px 0 15px' }}>
          <button onClick={handleLogout} style={logoutBtnStyle}>🚪 Logout Portal</button>
        </div>
      </div>
      
      {/* ප්‍රධාන කෑල්ල */}
      <div style={{ flex: 1, padding: '40px 50px', overflowY: 'auto' }}>
        {renderContent()}
      </div>

    </div>
  );
}

// --- GLOBAL SUB-COMPONENTS & STYLES ---
const SidebarBtn = ({ active, onClick, icon, text }) => (
  <button onClick={onClick} style={{ width: '100%', textAlign: 'left', padding: '14px 20px', backgroundColor: active ? 'rgba(255,255,255,0.15)' : 'transparent', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer', fontSize: '15px', display: 'flex', alignItems: 'center', gap: '15px', fontWeight: active ? 'bold' : 'normal', transition: '0.2s' }}>
    <span style={{ fontSize: '18px' }}>{icon}</span> {text}
  </button>
);

const DashboardCard = ({ title, count, icon, color, textColor }) => (
  <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', borderLeft: `5px solid ${textColor}` }}>
    <div><p style={{ margin: '0 0 5px 0', color: '#64748b', fontSize: '13px', fontWeight: 'bold' }}>{title}</p><h2 style={{ margin: 0, color: '#1e293b', fontSize: '22px' }}>{count}</h2></div>
    <div style={{ width: '55px', height: '55px', borderRadius: '12px', backgroundColor: color, display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: '26px' }}>{icon}</div>
  </div>
);

const labelStyle = { display: 'block', marginBottom: '6px', color: '#475569', fontSize: '13px', fontWeight: 'bold' };
const disabledInput = { width: '100%', padding: '12px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f1f5f9', color: '#334155', outline: 'none', boxSizing: 'border-box', fontSize: '14px' };
const downloadBtnStyle = { padding: '8px 15px', backgroundColor: '#eff6ff', color: '#1d4ed8', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px', textDecoration: 'none', display: 'inline-block' };
const videoBtnStyle = { padding: '8px 15px', backgroundColor: '#ecfdf5', color: '#047857', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px', textDecoration: 'none', display: 'inline-block' };
const startQuizBtn = { padding: '8px 16px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' };
const logoutBtnStyle = { width: '100%', padding: '12px', backgroundColor: '#dc2626', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '15px', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '10px' };
